window.CODE_LIBRARY = [{"id":"async_fifo","title":"Asynchronous FIFO","group":"Memory & FIFOs","level":"Advanced","featured":true,"summary":"Passes data safely between two unrelated clocks, using Gray-code pointers and 2-flip-flop synchronizers. A favourite interview question.","how":["Writes happen on wclk and reads on rclk. The data sits in a shared memory.","Each side keeps its own pointer, with one extra bit so that full and empty can be told apart.","Pointers cross to the other clock domain in Gray code, where only one bit changes at a time, through two flip-flops.","Empty: the read pointer has caught up with the write pointer. Full: the top two Gray bits differ and the rest match.","A simulator cannot show metastability, so passing the testbench does not prove the clock crossing is safe in hardware. For real chips, run CDC checks and constrain the crossing paths."],"diagram":"  WRITE side (wclk)                          READ side (rclk)\n  wdata ───────────►[  dual-clock memory  ]───────────► rdata\n  winc ──► write pointer ──► Gray ──► [FF][FF] ──► empty? ◄── read pointer ◄── rinc\n  wfull ◄── full? ◄── [FF][FF] ◄── Gray ◄── read pointer","try":"Change ASIZE to 4 (16 entries). The testbench uses DEPTH = 8, so update DEPTH and the .ASIZE value in it too.","expect":"PASS: async_fifo, 3064 items crossed between two clocks in order (full and empty both exercised)","v":"// Asynchronous FIFO: the write side and the read side use DIFFERENT, unrelated clocks.\n// This is the classic Gray-code pointer design (described by Clifford Cummings, SNUG 2002).\n//\n//  * Each pointer is sent to the other clock domain in GRAY code: only one bit changes at a\n//    time, so a sample taken during a change is either the old value or the new value.\n//  * Every crossing goes through a 2-flip-flop synchronizer (protects against metastability).\n//  * 'wfull' is decided in the write domain and 'rempty' in the read domain. Both are\n//    cautious: they can stay set a few cycles longer than necessary, but never clear too early.\n//\n// Depth = 2^ASIZE. ASIZE must be at least 2. Reset both sides together.\n\nmodule sync_2ff #(parameter WIDTH = 5) (\n    input  wire             clk,\n    input  wire             rst_n,\n    input  wire [WIDTH-1:0] d,\n    output reg  [WIDTH-1:0] q\n);\n    reg [WIDTH-1:0] meta;   // first stage: may go metastable, never use it for logic\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) {q, meta} <= {(2*WIDTH){1'b0}};\n        else        {q, meta} <= {meta, d};\n    end\nendmodule\n\nmodule async_fifo #(parameter DSIZE = 8, parameter ASIZE = 4) (\n    // write side\n    input  wire             wclk,\n    input  wire             wrst_n,\n    input  wire             winc,      // 1 = write wdata (ignored when full)\n    input  wire [DSIZE-1:0] wdata,\n    output reg              wfull,\n    // read side\n    input  wire             rclk,\n    input  wire             rrst_n,\n    input  wire             rinc,      // 1 = remove the item shown on rdata (ignored when empty)\n    output wire [DSIZE-1:0] rdata,     // oldest item, valid while rempty is 0\n    output reg              rempty\n);\n    reg [DSIZE-1:0] mem [0:(1<<ASIZE)-1];\n\n    // pointers have one extra bit so that \"full\" and \"empty\" can be told apart\n    reg  [ASIZE:0] wbin, wptr;       // write pointer in binary and in Gray code\n    reg  [ASIZE:0] rbin, rptr;       // read pointer in binary and in Gray code\n    wire [ASIZE:0] wq2_rptr;         // read pointer as seen by the write side\n    wire [ASIZE:0] rq2_wptr;         // write pointer as seen by the read side\n\n    sync_2ff #(.WIDTH(ASIZE+1)) sync_r2w (.clk(wclk), .rst_n(wrst_n), .d(rptr), .q(wq2_rptr));\n    sync_2ff #(.WIDTH(ASIZE+1)) sync_w2r (.clk(rclk), .rst_n(rrst_n), .d(wptr), .q(rq2_wptr));\n\n    // ------------------------- write clock domain -------------------------\n    wire           do_write   = winc && !wfull;\n    wire [ASIZE:0] wbin_next  = wbin + do_write;\n    wire [ASIZE:0] wgray_next = (wbin_next >> 1) ^ wbin_next;\n    // Full: the write pointer is exactly one lap ahead of the read pointer.\n    // In Gray code that means the top TWO bits differ and all other bits match.\n    wire           wfull_next = (wgray_next == {~wq2_rptr[ASIZE:ASIZE-1], wq2_rptr[ASIZE-2:0]});\n\n    always @(posedge wclk) begin\n        if (do_write) mem[wbin[ASIZE-1:0]] <= wdata;\n    end\n\n    always @(posedge wclk or negedge wrst_n) begin\n        if (!wrst_n) begin\n            wbin <= {(ASIZE+1){1'b0}};  wptr <= {(ASIZE+1){1'b0}};  wfull <= 1'b0;\n        end else begin\n            wbin <= wbin_next;          wptr <= wgray_next;          wfull <= wfull_next;\n        end\n    end\n\n    // ------------------------- read clock domain --------------------------\n    wire           do_read     = rinc && !rempty;\n    wire [ASIZE:0] rbin_next   = rbin + do_read;\n    wire [ASIZE:0] rgray_next  = (rbin_next >> 1) ^ rbin_next;\n    // Empty: the read pointer has caught up with the write pointer.\n    wire           rempty_next = (rgray_next == rq2_wptr);\n\n    always @(posedge rclk or negedge rrst_n) begin\n        if (!rrst_n) begin\n            rbin <= {(ASIZE+1){1'b0}};  rptr <= {(ASIZE+1){1'b0}};  rempty <= 1'b1;\n        end else begin\n            rbin <= rbin_next;          rptr <= rgray_next;          rempty <= rempty_next;\n        end\n    end\n\n    assign rdata = mem[rbin[ASIZE-1:0]];\nendmodule\n","sv":"// Asynchronous FIFO: the write side and the read side use DIFFERENT, unrelated clocks.\n// This is the classic Gray-code pointer design (described by Clifford Cummings, SNUG 2002).\n//\n//  * Each pointer is sent to the other clock domain in GRAY code: only one bit changes at a\n//    time, so a sample taken during a change is either the old value or the new value.\n//  * Every crossing goes through a 2-flip-flop synchronizer (protects against metastability).\n//  * 'wfull' is decided in the write domain and 'rempty' in the read domain. Both are\n//    cautious: they can stay set a few cycles longer than necessary, but never clear too early.\n//\n// Depth = 2^ASIZE. ASIZE must be at least 2. Reset both sides together.\n\nmodule sync_2ff #(parameter int WIDTH = 5) (\n    input  logic             clk,\n    input  logic             rst_n,\n    input  logic [WIDTH-1:0] d,\n    output logic [WIDTH-1:0] q\n);\n    logic [WIDTH-1:0] meta;   // first stage: may go metastable, never use it for logic\n\n    always_ff @(posedge clk or negedge rst_n) begin\n        if (!rst_n) {q, meta} <= '0;\n        else        {q, meta} <= {meta, d};\n    end\nendmodule\n\nmodule async_fifo #(parameter int DSIZE = 8, parameter int ASIZE = 4) (\n    // write side\n    input  logic             wclk,\n    input  logic             wrst_n,\n    input  logic             winc,      // 1 = write wdata (ignored when full)\n    input  logic [DSIZE-1:0] wdata,\n    output logic             wfull,\n    // read side\n    input  logic             rclk,\n    input  logic             rrst_n,\n    input  logic             rinc,      // 1 = remove the item shown on rdata (ignored when empty)\n    output logic [DSIZE-1:0] rdata,     // oldest item, valid while rempty is 0\n    output logic             rempty\n);\n    localparam int DEPTH = 1 << ASIZE;\n    typedef logic [ASIZE:0] ptr_t;      // one extra bit tells \"full\" and \"empty\" apart\n\n    logic [DSIZE-1:0] mem [0:DEPTH-1];\n\n    ptr_t wbin, wptr;                   // write pointer in binary and in Gray code\n    ptr_t rbin, rptr;                   // read pointer in binary and in Gray code\n    ptr_t wq2_rptr;                     // read pointer as seen by the write side\n    ptr_t rq2_wptr;                     // write pointer as seen by the read side\n\n    sync_2ff #(.WIDTH(ASIZE+1)) sync_r2w (.clk(wclk), .rst_n(wrst_n), .d(rptr), .q(wq2_rptr));\n    sync_2ff #(.WIDTH(ASIZE+1)) sync_w2r (.clk(rclk), .rst_n(rrst_n), .d(wptr), .q(rq2_wptr));\n\n    // ------------------------- write clock domain -------------------------\n    wire do_write = winc && !wfull;\n    ptr_t wbin_next, wgray_next;\n    assign wbin_next  = wbin + do_write;\n    assign wgray_next = (wbin_next >> 1) ^ wbin_next;\n    // Full: the write pointer is exactly one lap ahead of the read pointer.\n    // In Gray code that means the top TWO bits differ and all other bits match.\n    wire wfull_next = (wgray_next == {~wq2_rptr[ASIZE:ASIZE-1], wq2_rptr[ASIZE-2:0]});\n\n    always_ff @(posedge wclk) begin\n        if (do_write) mem[wbin[ASIZE-1:0]] <= wdata;\n    end\n\n    always_ff @(posedge wclk or negedge wrst_n) begin\n        if (!wrst_n) begin\n            wbin <= '0;         wptr <= '0;          wfull <= 1'b0;\n        end else begin\n            wbin <= wbin_next;  wptr <= wgray_next;  wfull <= wfull_next;\n        end\n    end\n\n    // ------------------------- read clock domain --------------------------\n    wire do_read = rinc && !rempty;\n    ptr_t rbin_next, rgray_next;\n    assign rbin_next  = rbin + do_read;\n    assign rgray_next = (rbin_next >> 1) ^ rbin_next;\n    // Empty: the read pointer has caught up with the write pointer.\n    wire rempty_next = (rgray_next == rq2_wptr);\n\n    always_ff @(posedge rclk or negedge rrst_n) begin\n        if (!rrst_n) begin\n            rbin <= '0;         rptr <= '0;          rempty <= 1'b1;\n        end else begin\n            rbin <= rbin_next;  rptr <= rgray_next;  rempty <= rempty_next;\n        end\n    end\n\n    assign rdata = mem[rbin[ASIZE-1:0]];\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_async_fifo;\n    localparam DEPTH = 8;\n    reg        wclk = 0, rclk = 0, wrst_n = 0, rrst_n = 0;\n    reg        winc = 0, rinc = 0;\n    reg  [7:0] wdata = 0;\n    wire [7:0] rdata;\n    wire       wfull, rempty;\n\n    integer whalf = 5, rhalf = 7;          // half clock periods, changed during the test\n    integer wprob = 0, rprob = 0;          // chance (0..4 out of 4) of trying to write / read\n    integer written = 0, got = 0, errors = 0, saw_full = 0, saw_empty = 0;\n    reg  [7:0] scoreboard [0:63];          // what should come out, in order\n\n    async_fifo #(.DSIZE(8), .ASIZE(3)) dut (\n        .wclk(wclk), .wrst_n(wrst_n), .winc(winc), .wdata(wdata), .wfull(wfull),\n        .rclk(rclk), .rrst_n(rrst_n), .rinc(rinc), .rdata(rdata), .rempty(rempty));\n\n    always #(whalf) wclk = ~wclk;\n    always #(rhalf) rclk = ~rclk;\n\n    // drive inputs on falling edges\n    always @(negedge wclk) begin winc <= (($random & 3) < wprob); wdata <= $random; end\n    always @(negedge rclk) begin rinc <= (($random & 3) < rprob); end\n\n    // remember every accepted write\n    always @(posedge wclk) if (wrst_n && winc && !wfull) begin\n        scoreboard[written % 64] = wdata;\n        written = written + 1;\n        if (written - got > DEPTH) begin errors = errors + 1; $display(\"FAIL: overflow, %0d items in a FIFO of %0d\", written - got, DEPTH); end\n    end\n    // check every accepted read\n    always @(posedge rclk) if (rrst_n && rinc && !rempty) begin\n        if (got >= written) begin errors = errors + 1; $display(\"FAIL: read from an empty FIFO\"); end\n        else if (rdata !== scoreboard[got % 64]) begin\n            errors = errors + 1; if (errors < 8) $display(\"FAIL: item %0d was %h, expected %h\", got, rdata, scoreboard[got % 64]);\n        end\n        got = got + 1;\n    end\n    always @(posedge wclk) if (wfull)  saw_full  = saw_full + 1;\n    always @(posedge rclk) if (rempty) saw_empty = saw_empty + 1;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_async_fifo);\n        #40 wrst_n = 1; rrst_n = 1;\n\n        // 1) write only: exactly DEPTH items must be accepted, then full\n        wprob = 4; rprob = 0; #600;\n        if (!wfull || written != DEPTH) begin errors = errors + 1; $display(\"FAIL: filled with %0d items, full=%b\", written, wfull); end\n        // 2) read only: everything comes back, then empty\n        wprob = 0; rprob = 4; #800;\n        if (!rempty || got != written) begin errors = errors + 1; $display(\"FAIL: drained %0d of %0d, empty=%b\", got, written, rempty); end\n        // 3) fast writer, slow reader\n        whalf = 3;  rhalf = 11; wprob = 3; rprob = 3; #30000;\n        // 4) slow writer, fast reader\n        whalf = 13; rhalf = 4;  wprob = 3; rprob = 3; #30000;\n        // 5) almost equal clocks\n        whalf = 5;  rhalf = 6;  wprob = 2; rprob = 2; #30000;\n        // final drain\n        wprob = 0; rprob = 4; #1000;\n        if (got != written || !rempty) begin errors = errors + 1; $display(\"FAIL: %0d written but %0d read\", written, got); end\n\n        if (errors == 0 && written > 1000 && saw_full > 0 && saw_empty > 0)\n            $display(\"PASS: async_fifo, %0d items crossed between two clocks in order (full and empty both exercised)\", got);\n        else\n            $display(\"FAIL: %0d errors, %0d written\", errors, written);\n        $finish;\n    end\nendmodule\n"},{"id":"sync_fifo","title":"Synchronous FIFO","group":"Memory & FIFOs","level":"Intermediate","summary":"A first-in, first-out queue on a single clock, with full, empty and count flags.","how":["A memory plus a write pointer and a read pointer.","The pointers have one extra bit: equal means empty, same address but different top bit means full.","Writes when full and reads when empty are ignored."],"try":"Add 'almost_full' and 'almost_empty' flags using count.","expect":"PASS: sync_fifo, 4000 random cycles (full 1276 times, empty 1293 times)","v":"// Synchronous FIFO (first in, first out): one clock for both writing and reading.\n// The oldest item is always visible on rdata while the FIFO is not empty.\n// Depth is 2^ADDR_W. The pointers have one extra bit to tell \"full\" from \"empty\".\nmodule sync_fifo #(parameter WIDTH = 8, parameter ADDR_W = 4) (\n    input  wire             clk,\n    input  wire             rst,\n    input  wire             wr_en,\n    input  wire [WIDTH-1:0] wdata,\n    output wire             full,\n    input  wire             rd_en,\n    output wire [WIDTH-1:0] rdata,\n    output wire             empty,\n    output wire [ADDR_W:0]  count      // how many items are stored\n);\n    reg [WIDTH-1:0] mem [0:(1<<ADDR_W)-1];\n    reg [ADDR_W:0]  wptr, rptr;\n\n    wire do_write = wr_en && !full;    // writes to a full FIFO are ignored\n    wire do_read  = rd_en && !empty;   // reads from an empty FIFO are ignored\n\n    always @(posedge clk) begin\n        if (do_write) mem[wptr[ADDR_W-1:0]] <= wdata;\n    end\n\n    always @(posedge clk) begin\n        if (rst) begin\n            wptr <= {(ADDR_W+1){1'b0}};\n            rptr <= {(ADDR_W+1){1'b0}};\n        end else begin\n            if (do_write) wptr <= wptr + 1'b1;\n            if (do_read)  rptr <= rptr + 1'b1;\n        end\n    end\n\n    assign rdata = mem[rptr[ADDR_W-1:0]];\n    assign empty = (wptr == rptr);\n    assign full  = (wptr[ADDR_W] != rptr[ADDR_W]) && (wptr[ADDR_W-1:0] == rptr[ADDR_W-1:0]);\n    assign count = wptr - rptr;\nendmodule\n","sv":"// Synchronous FIFO (first in, first out): one clock for both writing and reading.\n// The oldest item is always visible on rdata while the FIFO is not empty.\n// Depth is 2^ADDR_W. The pointers have one extra bit to tell \"full\" from \"empty\".\nmodule sync_fifo #(parameter int WIDTH = 8, parameter int ADDR_W = 4) (\n    input  logic             clk,\n    input  logic             rst,\n    input  logic             wr_en,\n    input  logic [WIDTH-1:0] wdata,\n    output logic             full,\n    input  logic             rd_en,\n    output logic [WIDTH-1:0] rdata,\n    output logic             empty,\n    output logic [ADDR_W:0]  count      // how many items are stored\n);\n    logic [WIDTH-1:0] mem [0:(1<<ADDR_W)-1];\n    logic [ADDR_W:0]  wptr, rptr;\n\n    wire do_write = wr_en && !full;    // writes to a full FIFO are ignored\n    wire do_read  = rd_en && !empty;   // reads from an empty FIFO are ignored\n\n    always_ff @(posedge clk) begin\n        if (do_write) mem[wptr[ADDR_W-1:0]] <= wdata;\n    end\n\n    always_ff @(posedge clk) begin\n        if (rst) begin\n            wptr <= '0;\n            rptr <= '0;\n        end else begin\n            if (do_write) wptr <= wptr + 1'b1;\n            if (do_read)  rptr <= rptr + 1'b1;\n        end\n    end\n\n    assign rdata = mem[rptr[ADDR_W-1:0]];\n    assign empty = (wptr == rptr);\n    assign full  = (wptr[ADDR_W] != rptr[ADDR_W]) && (wptr[ADDR_W-1:0] == rptr[ADDR_W-1:0]);\n    assign count = wptr - rptr;\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_sync_fifo;\n    reg        clk = 0, rst = 1, wr_en = 0, rd_en = 0;\n    reg  [7:0] wdata = 0;\n    wire [7:0] rdata;\n    wire       full, empty;\n    wire [3:0] count;                 // depth 8, so count needs 4 bits\n    // a simple software copy of the FIFO to compare against\n    reg  [7:0] model [0:7];\n    integer head = 0, size = 0, i, errors = 0, fulls = 0, empties = 0, wr_bias;\n    reg did_write, did_read;\n\n    sync_fifo #(.WIDTH(8), .ADDR_W(3)) dut (.clk(clk), .rst(rst), .wr_en(wr_en), .wdata(wdata), .full(full),\n                                             .rd_en(rd_en), .rdata(rdata), .empty(empty), .count(count));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_sync_fifo);\n        repeat (2) @(negedge clk);\n        rst = 0;\n        for (i = 0; i < 4000; i = i + 1) begin\n            wr_bias = ((i / 500) % 2 == 0) ? 3 : 1;        // sometimes fill up, sometimes drain\n            wr_en = (($random & 3) < wr_bias);\n            rd_en = (($random & 3) < 4 - wr_bias);\n            wdata = $random;\n            #1;\n            if (full !== (size == 8) || empty !== (size == 0) || count !== size) begin\n                errors = errors + 1; if (errors < 5) $display(\"FAIL: step %0d flags full=%b empty=%b count=%0d, expected size %0d\", i, full, empty, count, size);\n            end\n            if (size > 0 && rdata !== model[head]) begin\n                errors = errors + 1; if (errors < 5) $display(\"FAIL: step %0d rdata=%h expected %h\", i, rdata, model[head]);\n            end\n            if (full) fulls = fulls + 1;\n            if (empty) empties = empties + 1;\n            did_write = wr_en && (size < 8);\n            did_read  = rd_en && (size > 0);\n            @(posedge clk);\n            if (did_write) model[(head + size) % 8] = wdata;\n            if (did_read)  head = (head + 1) % 8;\n            size = size + did_write - did_read;\n            @(negedge clk);\n        end\n        if (errors == 0 && fulls > 0 && empties > 0) $display(\"PASS: sync_fifo, 4000 random cycles (full %0d times, empty %0d times)\", fulls, empties);\n        else                                         $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"ram","title":"Dual-port RAM","group":"Memory & FIFOs","level":"Beginner","summary":"One write port and one read port with a registered read, the style FPGA tools turn into block RAM.","how":["Writing happens on the clock edge when we is 1.","The read data appears one clock after the address.","Reading and writing the same address in the same cycle returns the old value."],"try":"Make a single-port version that shares one address for reading and writing.","expect":"PASS: ram, 2000 random reads and writes","v":"// Simple dual-port RAM: one write port and one read port. The read is registered, so data\n// appears one clock after the address. FPGA tools map this style onto built-in block RAM.\n// Reading and writing the same address in the same cycle returns the OLD value.\nmodule ram #(parameter WIDTH = 8, parameter ADDR_W = 8) (\n    input  wire              clk,\n    input  wire              we,       // write enable\n    input  wire [ADDR_W-1:0] waddr,\n    input  wire [WIDTH-1:0]  wdata,\n    input  wire [ADDR_W-1:0] raddr,\n    output reg  [WIDTH-1:0]  rdata\n);\n    reg [WIDTH-1:0] mem [0:(1<<ADDR_W)-1];\n\n    always @(posedge clk) begin\n        if (we) mem[waddr] <= wdata;\n        rdata <= mem[raddr];\n    end\nendmodule\n","sv":"// Simple dual-port RAM: one write port and one read port. The read is registered, so data\n// appears one clock after the address. FPGA tools map this style onto built-in block RAM.\n// Reading and writing the same address in the same cycle returns the OLD value.\nmodule ram #(parameter int WIDTH = 8, parameter int ADDR_W = 8) (\n    input  logic              clk,\n    input  logic              we,      // write enable\n    input  logic [ADDR_W-1:0] waddr,\n    input  logic [WIDTH-1:0]  wdata,\n    input  logic [ADDR_W-1:0] raddr,\n    output logic [WIDTH-1:0]  rdata\n);\n    logic [WIDTH-1:0] mem [0:(1<<ADDR_W)-1];\n\n    always_ff @(posedge clk) begin\n        if (we) mem[waddr] <= wdata;\n        rdata <= mem[raddr];\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_ram;\n    reg        clk = 0, we = 0;\n    reg  [3:0] waddr = 0, raddr = 0;\n    reg  [7:0] wdata = 0;\n    wire [7:0] rdata;\n    reg  [7:0] model [0:15];\n    reg  [7:0] expected;\n    integer i, errors = 0;\n\n    ram #(.WIDTH(8), .ADDR_W(4)) dut (.clk(clk), .we(we), .waddr(waddr), .wdata(wdata), .raddr(raddr), .rdata(rdata));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_ram);\n        // fill every address first, so every later read has a known value\n        for (i = 0; i < 16; i = i + 1) begin\n            @(negedge clk); we = 1; waddr = i; wdata = $random; model[i] = wdata;\n        end\n        for (i = 0; i < 2000; i = i + 1) begin\n            @(negedge clk);\n            we = $random; waddr = $random; wdata = $random; raddr = (i % 7 == 0) ? waddr : $random;\n            @(posedge clk);\n            expected = model[raddr];              // old value, even if writing the same address\n            if (we) model[waddr] = wdata;\n            @(negedge clk);\n            we = 0;\n            if (rdata !== expected) begin errors = errors + 1; if (errors < 5) $display(\"FAIL: step %0d addr %0d read %h expected %h\", i, raddr, rdata, expected); end\n        end\n        if (errors == 0) $display(\"PASS: ram, 2000 random reads and writes\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"mux4","title":"4-to-1 multiplexer","group":"Basics","level":"Beginner","summary":"Chooses one of four inputs. The most basic building block.","how":["A case statement picks the input named by sel.","Every case gives y a value, so no unwanted latch is created."],"try":"Turn it into an 8-to-1 multiplexer.","expect":"PASS: mux4, 200 random checks","v":"// 4-to-1 multiplexer: 'sel' chooses which input goes to the output.\nmodule mux4 #(parameter WIDTH = 8) (\n    input  wire [WIDTH-1:0] d0, d1, d2, d3,\n    input  wire [1:0]       sel,\n    output reg  [WIDTH-1:0] y\n);\n    always @(*) begin\n        case (sel)\n            2'b00:   y = d0;\n            2'b01:   y = d1;\n            2'b10:   y = d2;\n            default: y = d3;\n        endcase\n    end\nendmodule\n","sv":"// 4-to-1 multiplexer: 'sel' chooses which input goes to the output.\nmodule mux4 #(parameter int WIDTH = 8) (\n    input  logic [WIDTH-1:0] d0, d1, d2, d3,\n    input  logic [1:0]       sel,\n    output logic [WIDTH-1:0] y\n);\n    always_comb begin\n        case (sel)\n            2'b00:   y = d0;\n            2'b01:   y = d1;\n            2'b10:   y = d2;\n            default: y = d3;\n        endcase\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_mux4;\n    reg  [7:0] d0, d1, d2, d3;\n    reg  [1:0] sel;\n    wire [7:0] y;\n    reg  [7:0] expected;\n    integer i, errors = 0;\n\n    mux4 #(.WIDTH(8)) dut (.d0(d0), .d1(d1), .d2(d2), .d3(d3), .sel(sel), .y(y));\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_mux4);\n        for (i = 0; i < 200; i = i + 1) begin\n            d0 = $random; d1 = $random; d2 = $random; d3 = $random; sel = i;\n            #1;\n            expected = (sel == 0) ? d0 : (sel == 1) ? d1 : (sel == 2) ? d2 : d3;\n            if (y !== expected) begin errors = errors + 1; $display(\"FAIL: sel=%0d y=%h expected %h\", sel, y, expected); end\n        end\n        if (errors == 0) $display(\"PASS: mux4, 200 random checks\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"ripple_adder","title":"Ripple-carry adder","group":"Basics","level":"Beginner","summary":"An adder built from 1-bit full adders with generate, showing how bigger circuits are made from small ones.","how":["A full adder adds two bits and a carry.","generate creates one full adder per bit and chains their carries.","It is simple but slow for wide numbers, because the carry travels through every bit."],"try":"Replace the generate block with a single 'assign {cout, sum} = a + b + cin;' and compare the Yosys cell counts.","expect":"PASS: ripple_adder, 502 checks","v":"// Ripple-carry adder built from 1-bit full adders. The carry \"ripples\" from bit to bit.\nmodule full_adder (\n    input  wire a, b, cin,\n    output wire sum, cout\n);\n    assign sum  = a ^ b ^ cin;\n    assign cout = (a & b) | (cin & (a ^ b));\nendmodule\n\nmodule ripple_adder #(parameter WIDTH = 8) (\n    input  wire [WIDTH-1:0] a, b,\n    input  wire             cin,\n    output wire [WIDTH-1:0] sum,\n    output wire             cout\n);\n    wire [WIDTH:0] carry;\n    assign carry[0] = cin;\n    assign cout     = carry[WIDTH];\n\n    genvar i;\n    generate\n        for (i = 0; i < WIDTH; i = i + 1) begin : bit_slice\n            full_adder fa (.a(a[i]), .b(b[i]), .cin(carry[i]), .sum(sum[i]), .cout(carry[i+1]));\n        end\n    endgenerate\nendmodule\n","sv":"// Ripple-carry adder built from 1-bit full adders. The carry \"ripples\" from bit to bit.\nmodule full_adder (\n    input  logic a, b, cin,\n    output logic sum, cout\n);\n    assign sum  = a ^ b ^ cin;\n    assign cout = (a & b) | (cin & (a ^ b));\nendmodule\n\nmodule ripple_adder #(parameter int WIDTH = 8) (\n    input  logic [WIDTH-1:0] a, b,\n    input  logic             cin,\n    output logic [WIDTH-1:0] sum,\n    output logic             cout\n);\n    wire [WIDTH:0] carry;\n    assign carry[0] = cin;\n    assign cout     = carry[WIDTH];\n\n    for (genvar i = 0; i < WIDTH; i++) begin : bit_slice\n        full_adder fa (.a(a[i]), .b(b[i]), .cin(carry[i]), .sum(sum[i]), .cout(carry[i+1]));\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_ripple_adder;\n    reg  [7:0] a, b;\n    reg        cin;\n    wire [7:0] sum;\n    wire       cout;\n    integer i, errors = 0;\n\n    ripple_adder #(.WIDTH(8)) dut (.a(a), .b(b), .cin(cin), .sum(sum), .cout(cout));\n\n    task check;\n        begin\n            #1;\n            if ({cout, sum} !== a + b + cin) begin\n                errors = errors + 1;\n                $display(\"FAIL: %0d + %0d + %0d gave %0d\", a, b, cin, {cout, sum});\n            end\n        end\n    endtask\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_ripple_adder);\n        a = 8'hFF; b = 8'hFF; cin = 1; check;      // largest case\n        a = 0;     b = 0;     cin = 0; check;      // smallest case\n        for (i = 0; i < 500; i = i + 1) begin a = $random; b = $random; cin = $random; check; end\n        if (errors == 0) $display(\"PASS: ripple_adder, 502 checks\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"seven_seg","title":"7-segment decoder","group":"Basics","level":"Beginner","summary":"Shows a hex digit (0 to F) on a 7-segment display.","how":["A lookup table written as a case statement.","seg is ordered g,f,e,d,c,b,a and 1 means the segment is on."],"try":"Add a 'blank' input that turns all segments off.","expect":"PASS: seven_seg, all 16 digits","v":"// Hex digit to 7-segment display decoder. seg = {g,f,e,d,c,b,a}, 1 = segment ON.\n// For a common-anode (active-low) display, invert the output: ~seg\nmodule seven_seg (\n    input  wire [3:0] hex,\n    output reg  [6:0] seg\n);\n    always @(*) begin\n        case (hex)\n            4'h0: seg = 7'b0111111;\n            4'h1: seg = 7'b0000110;\n            4'h2: seg = 7'b1011011;\n            4'h3: seg = 7'b1001111;\n            4'h4: seg = 7'b1100110;\n            4'h5: seg = 7'b1101101;\n            4'h6: seg = 7'b1111101;\n            4'h7: seg = 7'b0000111;\n            4'h8: seg = 7'b1111111;\n            4'h9: seg = 7'b1101111;\n            4'hA: seg = 7'b1110111;\n            4'hB: seg = 7'b1111100;\n            4'hC: seg = 7'b0111001;\n            4'hD: seg = 7'b1011110;\n            4'hE: seg = 7'b1111001;\n            default: seg = 7'b1110001;   // F\n        endcase\n    end\nendmodule\n","sv":"// Hex digit to 7-segment display decoder. seg = {g,f,e,d,c,b,a}, 1 = segment ON.\n// For a common-anode (active-low) display, invert the output: ~seg\nmodule seven_seg (\n    input  logic [3:0] hex,\n    output logic [6:0] seg\n);\n    always_comb begin\n        case (hex)\n            4'h0: seg = 7'b0111111;\n            4'h1: seg = 7'b0000110;\n            4'h2: seg = 7'b1011011;\n            4'h3: seg = 7'b1001111;\n            4'h4: seg = 7'b1100110;\n            4'h5: seg = 7'b1101101;\n            4'h6: seg = 7'b1111101;\n            4'h7: seg = 7'b0000111;\n            4'h8: seg = 7'b1111111;\n            4'h9: seg = 7'b1101111;\n            4'hA: seg = 7'b1110111;\n            4'hB: seg = 7'b1111100;\n            4'hC: seg = 7'b0111001;\n            4'hD: seg = 7'b1011110;\n            4'hE: seg = 7'b1111001;\n            default: seg = 7'b1110001;   // F\n        endcase\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_seven_seg;\n    reg  [3:0] hex;\n    wire [6:0] seg;\n    reg  [6:0] expected;\n    integer i, k, errors = 0;\n    // which of the segments a..g are lit for each digit, written as text\n    reg [8*7:1] lit [0:15];\n\n    seven_seg dut (.hex(hex), .seg(seg));\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_seven_seg);\n        lit[0]=\"abcdef \"; lit[1]=\"bc     \"; lit[2]=\"abdeg  \"; lit[3]=\"abcdg  \";\n        lit[4]=\"bcfg   \"; lit[5]=\"acdfg  \"; lit[6]=\"acdefg \"; lit[7]=\"abc    \";\n        lit[8]=\"abcdefg\"; lit[9]=\"abcdfg \"; lit[10]=\"abcefg \"; lit[11]=\"cdefg  \";\n        lit[12]=\"adef   \"; lit[13]=\"bcdeg  \"; lit[14]=\"adefg  \"; lit[15]=\"aefg   \";\n        for (i = 0; i < 16; i = i + 1) begin\n            hex = i; #1;\n            expected = 0;\n            for (k = 0; k < 7; k = k + 1)\n                if (lit[i][8*k+1 +: 8] >= \"a\" && lit[i][8*k+1 +: 8] <= \"g\")\n                    expected[lit[i][8*k+1 +: 8] - \"a\"] = 1'b1;\n            if (seg !== expected) begin errors = errors + 1; $display(\"FAIL: digit %h seg=%b expected %b\", hex, seg, expected); end\n        end\n        if (errors == 0) $display(\"PASS: seven_seg, all 16 digits\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"alu","title":"ALU","group":"Basics","level":"Intermediate","summary":"Eight operations (add, subtract, logic, shifts and compare) with carry and zero flags. The calculator inside a CPU.","how":["op selects the operation.","The extra bit on add and subtract becomes the carry or borrow.","zero is 1 when the result is 0."],"try":"Add an arithmetic right shift (keeps the sign bit) as a new operation.","expect":"PASS: alu, 2000 random checks","v":"// A small ALU (arithmetic logic unit): the \"calculator\" inside a processor.\n//   op: 000 add   001 subtract   010 AND   011 OR\n//       100 XOR   101 shift left 110 shift right   111 set-if-less-than (signed)\nmodule alu #(parameter WIDTH = 8) (\n    input  wire [WIDTH-1:0] a, b,\n    input  wire [2:0]       op,\n    output reg  [WIDTH-1:0] y,\n    output reg              carry,   // carry out of an add, or borrow of a subtract\n    output wire             zero     // 1 when the result is zero\n);\n    always @(*) begin\n        carry = 1'b0;\n        case (op)\n            3'b000: {carry, y} = {1'b0, a} + {1'b0, b};\n            3'b001: {carry, y} = {1'b0, a} - {1'b0, b};\n            3'b010: y = a & b;\n            3'b011: y = a | b;\n            3'b100: y = a ^ b;\n            3'b101: y = a << b[2:0];\n            3'b110: y = a >> b[2:0];\n            default: y = ($signed(a) < $signed(b)) ? {{(WIDTH-1){1'b0}}, 1'b1} : {WIDTH{1'b0}};\n        endcase\n    end\n    assign zero = (y == {WIDTH{1'b0}});\nendmodule\n","sv":"// A small ALU (arithmetic logic unit): the \"calculator\" inside a processor.\nmodule alu #(parameter int WIDTH = 8) (\n    input  logic [WIDTH-1:0] a, b,\n    input  logic [2:0]       op,\n    output logic [WIDTH-1:0] y,\n    output logic             carry,   // carry out of an add, or borrow of a subtract\n    output logic             zero     // 1 when the result is zero\n);\n    // named operation codes make the code easy to read\n    localparam logic [2:0] ADD = 3'b000, SUB = 3'b001, AND_ = 3'b010, OR_ = 3'b011,\n                           XOR_ = 3'b100, SHL = 3'b101, SHR = 3'b110, SLT = 3'b111;\n\n    always_comb begin\n        carry = 1'b0;\n        case (op)\n            ADD:     {carry, y} = {1'b0, a} + {1'b0, b};\n            SUB:     {carry, y} = {1'b0, a} - {1'b0, b};\n            AND_:    y = a & b;\n            OR_:     y = a | b;\n            XOR_:    y = a ^ b;\n            SHL:     y = a << b[2:0];\n            SHR:     y = a >> b[2:0];\n            default: y = ($signed(a) < $signed(b)) ? WIDTH'(1) : '0;   // SLT\n        endcase\n    end\n    assign zero = (y == '0);\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_alu;\n    reg  [7:0] a, b;\n    reg  [2:0] op;\n    wire [7:0] y;\n    wire       carry, zero;\n    reg  [8:0] want;      // {carry, result}\n    reg  [7:0] shifted;\n    integer i, errors = 0;\n\n    alu #(.WIDTH(8)) dut (.a(a), .b(b), .op(op), .y(y), .carry(carry), .zero(zero));\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_alu);\n        for (i = 0; i < 2000; i = i + 1) begin\n            a = $random; b = $random; op = i;\n            if (i % 50 == 0) b = a;              // force some \"equal\" cases (zero flag)\n            #1;\n            case (op)\n                0: want = a + b;\n                1: want = {(a < b), a - b};\n                2: want = {1'b0, a & b};\n                3: want = {1'b0, a | b};\n                4: want = {1'b0, a ^ b};\n                5: begin shifted = a << b[2:0]; want = {1'b0, shifted}; end\n                6: begin shifted = a >> b[2:0]; want = {1'b0, shifted}; end\n                default: want = {8'b0, ((a ^ 8'h80) < (b ^ 8'h80))};   // signed compare\n            endcase\n            if ({carry, y} !== want || zero !== (want[7:0] == 0)) begin\n                errors = errors + 1;\n                if (errors < 5) $display(\"FAIL: op=%0d a=%h b=%h got %b %h zero=%b, expected %h\", op, a, b, carry, y, zero, want);\n            end\n        end\n        if (errors == 0) $display(\"PASS: alu, 2000 random checks\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"counter","title":"Up/down counter","group":"Basics","level":"Beginner","summary":"A counter with reset, load, enable and direction control.","how":["Reset has the highest priority, then load, then counting.","It wraps around naturally at both ends."],"try":"Make it stop at a MAX value instead of wrapping.","expect":"PASS: counter, 2000 random clock cycles","v":"// Up/down counter with synchronous reset, enable and parallel load.\n// Priority: reset, then load, then count.\nmodule counter #(parameter WIDTH = 8) (\n    input  wire             clk,\n    input  wire             rst,      // 1 = clear to zero\n    input  wire             load,     // 1 = copy d into the counter\n    input  wire             en,       // 1 = count\n    input  wire             up,       // 1 = count up, 0 = count down\n    input  wire [WIDTH-1:0] d,\n    output reg  [WIDTH-1:0] q\n);\n    always @(posedge clk) begin\n        if (rst)       q <= {WIDTH{1'b0}};\n        else if (load) q <= d;\n        else if (en)   q <= up ? q + 1'b1 : q - 1'b1;\n    end\nendmodule\n","sv":"// Up/down counter with synchronous reset, enable and parallel load.\n// Priority: reset, then load, then count.\nmodule counter #(parameter int WIDTH = 8) (\n    input  logic             clk,\n    input  logic             rst,     // 1 = clear to zero\n    input  logic             load,    // 1 = copy d into the counter\n    input  logic             en,      // 1 = count\n    input  logic             up,      // 1 = count up, 0 = count down\n    input  logic [WIDTH-1:0] d,\n    output logic [WIDTH-1:0] q\n);\n    always_ff @(posedge clk) begin\n        if (rst)       q <= '0;\n        else if (load) q <= d;\n        else if (en)   q <= up ? q + 1'b1 : q - 1'b1;\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_counter;\n    reg        clk = 0, rst = 1, load = 0, en = 0, up = 1;\n    reg  [7:0] d = 0;\n    wire [7:0] q;\n    reg  [7:0] model = 0;\n    integer i, errors = 0;\n\n    counter #(.WIDTH(8)) dut (.clk(clk), .rst(rst), .load(load), .en(en), .up(up), .d(d), .q(q));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_counter);\n        repeat (2) @(negedge clk);\n        for (i = 0; i < 2000; i = i + 1) begin\n            // change inputs on the falling edge, check after the rising edge\n            rst  = ($random & 31) == 0;\n            load = ($random & 15) == 0;\n            en   = ($random & 3) != 0;\n            up   = (i < 1000) ? (($random & 7) != 0) : (($random & 7) == 0);\n            d    = $random;\n            @(posedge clk);\n            if (rst) model = 0; else if (load) model = d; else if (en) model = up ? model + 1 : model - 1;\n            @(negedge clk);\n            if (q !== model) begin errors = errors + 1; if (errors < 5) $display(\"FAIL: step %0d q=%0d expected %0d\", i, q, model); end\n        end\n        if (errors == 0) $display(\"PASS: counter, 2000 random clock cycles\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"shift_register","title":"Universal shift register","group":"Basics","level":"Beginner","summary":"Holds, shifts left, shifts right or loads in parallel. Used to turn serial data into parallel and back.","how":["mode selects hold, shift right, shift left or load.","ser_msb and ser_lsb are the bits that enter at each end."],"try":"Add a rotate mode where the bit that falls off comes back in at the other end.","expect":"PASS: shift_register, 2000 random clock cycles","v":"// Universal shift register.\n//   mode 00: hold          01: shift right (ser_msb enters at the top)\n//   mode 10: shift left (ser_lsb enters at the bottom)     11: parallel load\nmodule shift_register #(parameter WIDTH = 8) (\n    input  wire             clk,\n    input  wire             rst,\n    input  wire [1:0]       mode,\n    input  wire             ser_msb,\n    input  wire             ser_lsb,\n    input  wire [WIDTH-1:0] d,\n    output reg  [WIDTH-1:0] q\n);\n    always @(posedge clk) begin\n        if (rst) q <= {WIDTH{1'b0}};\n        else begin\n            case (mode)\n                2'b01:   q <= {ser_msb, q[WIDTH-1:1]};\n                2'b10:   q <= {q[WIDTH-2:0], ser_lsb};\n                2'b11:   q <= d;\n                default: q <= q;\n            endcase\n        end\n    end\nendmodule\n","sv":"// Universal shift register.\n//   mode 00: hold          01: shift right (ser_msb enters at the top)\n//   mode 10: shift left (ser_lsb enters at the bottom)     11: parallel load\nmodule shift_register #(parameter int WIDTH = 8) (\n    input  logic             clk,\n    input  logic             rst,\n    input  logic [1:0]       mode,\n    input  logic             ser_msb,\n    input  logic             ser_lsb,\n    input  logic [WIDTH-1:0] d,\n    output logic [WIDTH-1:0] q\n);\n    always_ff @(posedge clk) begin\n        if (rst) q <= '0;\n        else begin\n            case (mode)\n                2'b01:   q <= {ser_msb, q[WIDTH-1:1]};\n                2'b10:   q <= {q[WIDTH-2:0], ser_lsb};\n                2'b11:   q <= d;\n                default: q <= q;\n            endcase\n        end\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_shift_register;\n    reg        clk = 0, rst = 1, ser_msb = 0, ser_lsb = 0;\n    reg  [1:0] mode = 0;\n    reg  [7:0] d = 0;\n    wire [7:0] q;\n    reg  [7:0] model = 0;\n    integer i, errors = 0;\n\n    shift_register #(.WIDTH(8)) dut (.clk(clk), .rst(rst), .mode(mode), .ser_msb(ser_msb), .ser_lsb(ser_lsb), .d(d), .q(q));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_shift_register);\n        repeat (2) @(negedge clk);\n        rst = 0;\n        for (i = 0; i < 2000; i = i + 1) begin\n            mode = $random; ser_msb = $random; ser_lsb = $random; d = $random;\n            rst = ($random & 63) == 0;\n            @(posedge clk);\n            if (rst) model = 0;\n            else case (mode)\n                1: model = (model >> 1) | (ser_msb << 7);\n                2: model = (model << 1) | ser_lsb;\n                3: model = d;\n                default: ;\n            endcase\n            @(negedge clk);\n            if (q !== model) begin errors = errors + 1; if (errors < 5) $display(\"FAIL: step %0d q=%b expected %b\", i, q, model); end\n        end\n        if (errors == 0) $display(\"PASS: shift_register, 2000 random clock cycles\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"edge_detector","title":"Edge detector","group":"Timing & signals","level":"Beginner","summary":"Gives a one-clock pulse when a signal rises or falls.","how":["It remembers the signal from the previous clock.","Comparing old and new values shows which edge happened.","The input must already be synchronous to the clock."],"try":"Add a 2-flip-flop synchronizer in front, so it can take a signal from outside the chip.","expect":"PASS: edge_detector, saw 236 rising edges","v":"// Detects rising and falling edges of a signal. Each output is high for one clock cycle.\n// 'sig' must already be synchronous to clk (use a synchronizer for outside signals).\nmodule edge_detector (\n    input  wire clk,\n    input  wire rst,\n    input  wire sig,\n    output wire rise,\n    output wire fall,\n    output wire any_edge\n);\n    reg prev;   // the value of sig one clock ago\n\n    always @(posedge clk) begin\n        if (rst) prev <= 1'b0;\n        else     prev <= sig;\n    end\n\n    assign rise     =  sig & ~prev;\n    assign fall     = ~sig &  prev;\n    assign any_edge =  sig ^  prev;\nendmodule\n","sv":"// Detects rising and falling edges of a signal. Each output is high for one clock cycle.\n// 'sig' must already be synchronous to clk (use a synchronizer for outside signals).\nmodule edge_detector (\n    input  logic clk,\n    input  logic rst,\n    input  logic sig,\n    output logic rise,\n    output logic fall,\n    output logic any_edge\n);\n    logic prev;   // the value of sig one clock ago\n\n    always_ff @(posedge clk) begin\n        if (rst) prev <= 1'b0;\n        else     prev <= sig;\n    end\n\n    assign rise     =  sig & ~prev;\n    assign fall     = ~sig &  prev;\n    assign any_edge =  sig ^  prev;\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_edge_detector;\n    reg  clk = 0, rst = 1, sig = 0;\n    wire rise, fall, any_edge;\n    reg  last = 0;\n    integer i, errors = 0, rises = 0;\n\n    edge_detector dut (.clk(clk), .rst(rst), .sig(sig), .rise(rise), .fall(fall), .any_edge(any_edge));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_edge_detector);\n        repeat (2) @(negedge clk);\n        rst = 0;\n        for (i = 0; i < 1000; i = i + 1) begin\n            sig = $random;\n            #1;   // outputs react to sig right away\n            if (rise !== (sig & ~last) || fall !== (~sig & last) || any_edge !== (sig ^ last)) begin\n                errors = errors + 1; if (errors < 5) $display(\"FAIL: step %0d sig=%b last=%b\", i, sig, last);\n            end\n            if (rise) rises = rises + 1;\n            @(posedge clk); last = sig;\n            @(negedge clk);\n        end\n        if (errors == 0 && rises > 100) $display(\"PASS: edge_detector, saw %0d rising edges\", rises);\n        else                            $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"debouncer","title":"Button debouncer","group":"Timing & signals","level":"Intermediate","summary":"Cleans up a bouncing mechanical button so that one press counts once.","how":["Two flip-flops synchronize the button.","The output changes only after the input has stayed different for STABLE_CYCLES clocks.","Any bounce back restarts the timer."],"try":"Connect it to the edge detector to get one pulse per button press.","expect":"PASS: debouncer, 3 bouncy presses gave exactly 3 clean changes","v":"// Button debouncer. A mechanical button \"bounces\" for a few milliseconds when pressed.\n// The output only changes after the input has stayed the same for STABLE_CYCLES clocks.\n// Default: 120000 cycles = 10 ms with a 12 MHz clock.\nmodule debouncer #(parameter STABLE_CYCLES = 120000) (\n    input  wire clk,\n    input  wire rst,\n    input  wire noisy,     // straight from the button pin\n    output reg  clean\n);\n    localparam W = $clog2(STABLE_CYCLES + 1);\n    reg         sync0, sync1;   // two flip-flops bring the button into our clock domain\n    reg [W-1:0] count;\n\n    always @(posedge clk) begin\n        if (rst) begin\n            sync0 <= 1'b0; sync1 <= 1'b0;\n            count <= {W{1'b0}};\n            clean <= 1'b0;\n        end else begin\n            sync0 <= noisy;\n            sync1 <= sync0;\n            if (sync1 == clean)\n                count <= {W{1'b0}};                 // nothing new: start again\n            else if (count == STABLE_CYCLES - 1) begin\n                clean <= sync1;                     // stayed different long enough\n                count <= {W{1'b0}};\n            end else\n                count <= count + 1'b1;\n        end\n    end\nendmodule\n","sv":"// Button debouncer. A mechanical button \"bounces\" for a few milliseconds when pressed.\n// The output only changes after the input has stayed the same for STABLE_CYCLES clocks.\n// Default: 120000 cycles = 10 ms with a 12 MHz clock.\nmodule debouncer #(parameter int STABLE_CYCLES = 120000) (\n    input  logic clk,\n    input  logic rst,\n    input  logic noisy,     // straight from the button pin\n    output logic clean\n);\n    localparam int W = $clog2(STABLE_CYCLES + 1);\n    logic         sync0, sync1; // two flip-flops bring the button into our clock domain\n    logic [W-1:0] count;\n\n    always_ff @(posedge clk) begin\n        if (rst) begin\n            sync0 <= 1'b0; sync1 <= 1'b0;\n            count <= '0;\n            clean <= 1'b0;\n        end else begin\n            sync0 <= noisy;\n            sync1 <= sync0;\n            if (sync1 == clean)\n                count <= '0;                 // nothing new: start again\n            else if (count == STABLE_CYCLES - 1) begin\n                clean <= sync1;                     // stayed different long enough\n                count <= '0;\n            end else\n                count <= count + 1'b1;\n        end\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_debouncer;\n    reg  clk = 0, rst = 1, noisy = 0;\n    wire clean;\n    integer i, changes = 0, errors = 0;\n\n    debouncer #(.STABLE_CYCLES(8)) dut (.clk(clk), .rst(rst), .noisy(noisy), .clean(clean));\n    always #5 clk = ~clk;\n    always @(clean) if (!rst) changes = changes + 1;\n\n    // bounce quickly (never stable for 8 cycles), then settle on 'level'\n    task press(input level);\n        begin\n            for (i = 0; i < 20; i = i + 1) begin\n                @(negedge clk); noisy = ~noisy;          // flip, so each bounce lasts at most 4 clocks\n                repeat ($random & 3) @(negedge clk);\n            end\n            noisy = level;\n            repeat (20) @(negedge clk);\n        end\n    endtask\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_debouncer);\n        repeat (3) @(negedge clk);\n        rst = 0;\n        changes = 0;\n        press(1); if (clean !== 1'b1) begin errors = errors + 1; $display(\"FAIL: did not become 1\"); end\n        press(0); if (clean !== 1'b0) begin errors = errors + 1; $display(\"FAIL: did not become 0\"); end\n        press(1); if (clean !== 1'b1) begin errors = errors + 1; $display(\"FAIL: did not become 1 again\"); end\n        if (changes != 3) begin errors = errors + 1; $display(\"FAIL: output changed %0d times, expected 3 (bounces got through)\", changes); end\n        if (errors == 0) $display(\"PASS: debouncer, 3 bouncy presses gave exactly 3 clean changes\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"clock_divider","title":"Clock divider (tick generator)","group":"Timing & signals","level":"Beginner","summary":"Makes slow events from a fast clock, using a clock-enable tick.","how":["A counter runs from 0 to DIV-1.","tick pulses once every DIV clocks. Use it as an enable, not as a new clock."],"try":"Use tick as the enable of the counter design to count once per second.","expect":"PASS: clock_divider, 100 ticks exactly 5 clocks apart","v":"// Clock divider. 'tick' pulses for one cycle every DIV clocks; 'slow' toggles on each tick.\n// Best practice: use 'tick' as a clock ENABLE. Don't use 'slow' as a real clock in an FPGA.\nmodule clock_divider #(parameter DIV = 12000000) (\n    input  wire clk,\n    input  wire rst,\n    output reg  tick,\n    output reg  slow\n);\n    localparam W = $clog2(DIV);\n    reg [W-1:0] count;\n\n    always @(posedge clk) begin\n        if (rst) begin\n            count <= {W{1'b0}}; tick <= 1'b0; slow <= 1'b0;\n        end else if (count == DIV - 1) begin\n            count <= {W{1'b0}}; tick <= 1'b1; slow <= ~slow;\n        end else begin\n            count <= count + 1'b1; tick <= 1'b0;\n        end\n    end\nendmodule\n","sv":"// Clock divider. 'tick' pulses for one cycle every DIV clocks; 'slow' toggles on each tick.\n// Best practice: use 'tick' as a clock ENABLE. Don't use 'slow' as a real clock in an FPGA.\nmodule clock_divider #(parameter int DIV = 12000000) (\n    input  logic clk,\n    input  logic rst,\n    output logic tick,\n    output logic slow\n);\n    localparam int W = $clog2(DIV);\n    logic [W-1:0] count;\n\n    always_ff @(posedge clk) begin\n        if (rst) begin\n            count <= '0; tick <= 1'b0; slow <= 1'b0;\n        end else if (count == DIV - 1) begin\n            count <= '0; tick <= 1'b1; slow <= ~slow;\n        end else begin\n            count <= count + 1'b1; tick <= 1'b0;\n        end\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_clock_divider;\n    reg  clk = 0, rst = 1;\n    wire tick, slow;\n    integer i, since = 0, ticks = 0, errors = 0;\n    reg last_slow = 0;\n\n    clock_divider #(.DIV(5)) dut (.clk(clk), .rst(rst), .tick(tick), .slow(slow));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_clock_divider);\n        repeat (3) @(negedge clk);\n        rst = 0;\n        for (i = 0; i < 500; i = i + 1) begin\n            @(negedge clk);\n            since = since + 1;\n            if (tick) begin\n                ticks = ticks + 1;\n                if (since != 5) begin errors = errors + 1; $display(\"FAIL: tick after %0d clocks, expected 5\", since); end\n                if (slow === last_slow) begin errors = errors + 1; $display(\"FAIL: slow did not toggle\"); end\n                last_slow = slow; since = 0;\n            end else if (slow !== last_slow) begin errors = errors + 1; $display(\"FAIL: slow changed without a tick\"); end\n        end\n        if (errors == 0 && ticks == 100) $display(\"PASS: clock_divider, 100 ticks exactly 5 clocks apart\");\n        else                             $display(\"FAIL: %0d errors, %0d ticks\", errors, ticks);\n        $finish;\n    end\nendmodule\n"},{"id":"pwm","title":"PWM generator","group":"Timing & signals","level":"Beginner","summary":"Pulse width modulation for dimming LEDs and controlling motors.","how":["A free-running counter is compared with duty.","The output is high for duty out of every 256 clocks (8-bit)."],"try":"Slowly sweep duty up and down to make an LED 'breathe'.","expect":"PASS: pwm, high time equals duty for 12 settings","v":"// PWM (pulse width modulation): the output is high for 'duty' out of every 2^WIDTH clocks.\n// Used to dim LEDs and control motor speed.\nmodule pwm #(parameter WIDTH = 8) (\n    input  wire             clk,\n    input  wire             rst,\n    input  wire [WIDTH-1:0] duty,    // 0 = always off, larger = on longer\n    output wire             out\n);\n    reg [WIDTH-1:0] count;\n\n    always @(posedge clk) begin\n        if (rst) count <= {WIDTH{1'b0}};\n        else     count <= count + 1'b1;     // wraps around by itself\n    end\n\n    assign out = (count < duty);\nendmodule\n","sv":"// PWM (pulse width modulation): the output is high for 'duty' out of every 2^WIDTH clocks.\n// Used to dim LEDs and control motor speed.\nmodule pwm #(parameter int WIDTH = 8) (\n    input  logic             clk,\n    input  logic             rst,\n    input  logic [WIDTH-1:0] duty,    // 0 = always off, larger = on longer\n    output logic             out\n);\n    logic [WIDTH-1:0] count;\n\n    always_ff @(posedge clk) begin\n        if (rst) count <= '0;\n        else     count <= count + 1'b1;     // wraps around by itself\n    end\n\n    assign out = (count < duty);\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_pwm;\n    reg        clk = 0, rst = 1;\n    reg  [7:0] duty = 0;\n    wire       out;\n    integer i, k, high, errors = 0;\n\n    pwm #(.WIDTH(8)) dut (.clk(clk), .rst(rst), .duty(duty), .out(out));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_pwm);\n        repeat (2) @(negedge clk);\n        rst = 0;\n        for (k = 0; k < 12; k = k + 1) begin\n            case (k) 0: duty = 0; 1: duty = 1; 2: duty = 128; 3: duty = 255; default: duty = $random; endcase\n            high = 0;\n            for (i = 0; i < 256; i = i + 1) begin @(negedge clk); if (out) high = high + 1; end\n            if (high != duty) begin errors = errors + 1; $display(\"FAIL: duty %0d gave %0d high cycles out of 256\", duty, high); end\n        end\n        if (errors == 0) $display(\"PASS: pwm, high time equals duty for 12 settings\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"sequence_detector","title":"Sequence detector FSM (1011)","group":"State machines","level":"Intermediate","summary":"A Moore state machine that finds 1011 in a stream of bits, including overlapping matches.","how":["Each state means how much of 1011 has been seen.","One block stores the state, another works out the next state.","The SystemVerilog version uses a typedef enum for readable states."],"try":"Change it to detect 1101. Draw the state diagram first. You will also need to change the pattern in the testbench.","expect":"PASS: sequence_detector, found 1011 181 times with no mistakes","v":"// State machine that detects the bit pattern 1011 in a serial stream (overlaps allowed).\n// Moore machine: 'found' goes high for one cycle after the last bit has been clocked in.\nmodule sequence_detector (\n    input  wire clk,\n    input  wire rst,\n    input  wire din,\n    output wire found\n);\n    // each state remembers how much of \"1011\" we have seen so far\n    localparam [2:0] IDLE  = 3'd0,   // nothing useful yet\n                     S1    = 3'd1,   // seen 1\n                     S10   = 3'd2,   // seen 10\n                     S101  = 3'd3,   // seen 101\n                     S1011 = 3'd4;   // seen 1011\n\n    reg [2:0] state, next;\n\n    always @(posedge clk) begin\n        if (rst) state <= IDLE;\n        else     state <= next;\n    end\n\n    always @(*) begin\n        case (state)\n            IDLE:    next = din ? S1    : IDLE;\n            S1:      next = din ? S1    : S10;\n            S10:     next = din ? S101  : IDLE;\n            S101:    next = din ? S1011 : S10;\n            S1011:   next = din ? S1    : S10;\n            default: next = IDLE;\n        endcase\n    end\n\n    assign found = (state == S1011);\nendmodule\n","sv":"// State machine that detects the bit pattern 1011 in a serial stream (overlaps allowed).\n// Moore machine: 'found' goes high for one cycle after the last bit has been clocked in.\nmodule sequence_detector (\n    input  logic clk,\n    input  logic rst,\n    input  logic din,\n    output logic found\n);\n    // each state remembers how much of \"1011\" we have seen so far\n    typedef enum logic [2:0] { IDLE, S1, S10, S101, S1011 } state_t;\n    state_t state, next;\n\n    always_ff @(posedge clk) begin\n        if (rst) state <= IDLE;\n        else     state <= next;\n    end\n\n    always_comb begin\n        case (state)\n            IDLE:    if (din) next = S1;    else next = IDLE;\n            S1:      if (din) next = S1;    else next = S10;\n            S10:     if (din) next = S101;  else next = IDLE;\n            S101:    if (din) next = S1011; else next = S10;\n            S1011:   if (din) next = S1;    else next = S10;\n            default: next = IDLE;\n        endcase\n    end\n\n    assign found = (state == S1011);\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_sequence_detector;\n    reg  clk = 0, rst = 1, din = 0;\n    wire found;\n    reg  [3:0] last4 = 0;\n    integer i, seen = 0, hits = 0, errors = 0;\n\n    sequence_detector dut (.clk(clk), .rst(rst), .din(din), .found(found));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_sequence_detector);\n        repeat (2) @(negedge clk);\n        rst = 0;\n        for (i = 0; i < 3000; i = i + 1) begin\n            din = $random;\n            @(posedge clk); last4 = {last4[2:0], din}; seen = seen + 1;\n            @(negedge clk);\n            if (found !== (seen >= 4 && last4 == 4'b1011)) begin\n                errors = errors + 1; if (errors < 5) $display(\"FAIL: bit %0d last4=%b found=%b\", i, last4, found);\n            end\n            if (found) hits = hits + 1;\n        end\n        if (errors == 0 && hits > 50) $display(\"PASS: sequence_detector, found 1011 %0d times with no mistakes\", hits);\n        else                          $display(\"FAIL: %0d errors, %0d hits\", errors, hits);\n        $finish;\n    end\nendmodule\n"},{"id":"round_robin_arbiter","title":"Round-robin arbiter","group":"State machines","level":"Advanced","summary":"Lets several requesters share one resource fairly by taking turns.","how":["x & (~x + 1) keeps only the lowest 1 bit.","A mask gives priority to requesters above the last winner.","If nobody above is asking, it wraps around to the lowest requester."],"try":"Set N = 8 and update the testbench to match.","expect":"PASS: round_robin_arbiter, 2473 fair grants, nobody waited more than 3 turns","v":"// Round-robin arbiter: several users ask for one shared resource, and they take turns fairly.\n// 'gnt' is one-hot: at most one bit is 1. After a grant, that user gets the lowest priority.\nmodule round_robin_arbiter #(parameter N = 4) (\n    input  wire         clk,\n    input  wire         rst,\n    input  wire [N-1:0] req,\n    output wire [N-1:0] gnt\n);\n    reg [N-1:0] mask;    // 1 = this user still has priority in the current round\n\n    wire [N-1:0] masked      = req & mask;\n    wire [N-1:0] pick_masked = masked & (~masked + 1'b1);   // lowest 1 bit\n    wire [N-1:0] pick_any    = req & (~req + 1'b1);\n\n    assign gnt = (|masked) ? pick_masked : pick_any;        // wrap around if needed\n\n    always @(posedge clk) begin\n        if (rst)       mask <= {N{1'b1}};\n        else if (|gnt) mask <= ~(gnt | (gnt - 1'b1));       // only users above the winner\n    end\nendmodule\n","sv":"// Round-robin arbiter: several users ask for one shared resource, and they take turns fairly.\n// 'gnt' is one-hot: at most one bit is 1. After a grant, that user gets the lowest priority.\nmodule round_robin_arbiter #(parameter int N = 4) (\n    input  logic         clk,\n    input  logic         rst,\n    input  logic [N-1:0] req,\n    output logic [N-1:0] gnt\n);\n    logic [N-1:0] mask;   // 1 = this user still has priority in the current round\n\n    wire [N-1:0] masked      = req & mask;\n    wire [N-1:0] pick_masked = masked & (~masked + 1'b1);   // lowest 1 bit\n    wire [N-1:0] pick_any    = req & (~req + 1'b1);\n\n    assign gnt = (|masked) ? pick_masked : pick_any;        // wrap around if needed\n\n    always_ff @(posedge clk) begin\n        if (rst)       mask <= '1;\n        else if (|gnt) mask <= ~(gnt | (gnt - 1'b1));       // only users above the winner\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_round_robin_arbiter;\n    reg        clk = 0, rst = 1;\n    reg  [3:0] req = 0;\n    wire [3:0] gnt;\n    integer i, u, grants = 0, errors = 0;\n    integer waiting [0:3];\n    reg [3:0] g;\n\n    round_robin_arbiter #(.N(4)) dut (.clk(clk), .rst(rst), .req(req), .gnt(gnt));\n    always #5 clk = ~clk;\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_round_robin_arbiter);\n        for (u = 0; u < 4; u = u + 1) waiting[u] = 0;\n        repeat (2) @(negedge clk);\n        rst = 0;\n        // everyone asks at once: they must be served 0, 1, 2, 3, 0, 1, ...\n        req = 4'b1111;\n        for (i = 0; i < 12; i = i + 1) begin\n            #1;\n            if (gnt !== (4'b0001 << (i % 4))) begin errors = errors + 1; $display(\"FAIL: turn %0d gnt=%b\", i, gnt); end\n            @(negedge clk);\n        end\n        // random requests that stay up until granted\n        req = 0;\n        for (i = 0; i < 3000; i = i + 1) begin\n            req = req | ($random & $random);\n            #1;\n            g = gnt;\n            if ((g & ~req) !== 0 || (g & (g - 4'd1)) !== 0 || ((req != 0) && (g == 0))) begin\n                errors = errors + 1; if (errors < 5) $display(\"FAIL: req=%b gnt=%b\", req, g);\n            end\n            for (u = 0; u < 4; u = u + 1) begin\n                if (g[u]) begin waiting[u] = 0; grants = grants + 1; end\n                else if (req[u]) waiting[u] = waiting[u] + 1;\n                if (waiting[u] > 3) begin errors = errors + 1; if (errors < 5) $display(\"FAIL: user %0d waited %0d turns\", u, waiting[u]); end\n            end\n            @(negedge clk);\n            req = req & ~g;                 // the winner drops its request\n        end\n        if (errors == 0 && grants > 1000) $display(\"PASS: round_robin_arbiter, %0d fair grants, nobody waited more than 3 turns\", grants);\n        else                              $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"},{"id":"uart_tx","title":"UART transmitter","group":"Interfaces","level":"Intermediate","summary":"Sends bytes over a serial line (8N1), as used to talk to a computer.","how":["The line idles high. A frame is a start bit, 8 data bits (lowest first) and a stop bit.","CLKS_PER_BIT sets the baud rate: clock frequency divided by baud rate.","A 4-state machine steps through the frame."],"try":"Add an even parity bit before the stop bit.","expect":"PASS: uart_tx, 50 bytes decoded correctly from the serial line","v":"// UART transmitter, 8N1: start bit (0), 8 data bits (lowest first), stop bit (1).\n// CLKS_PER_BIT = clock frequency / baud rate.  Example: 12 MHz / 115200 = 104.\nmodule uart_tx #(parameter CLKS_PER_BIT = 104) (\n    input  wire       clk,\n    input  wire       rst,\n    input  wire       start,     // pulse for one clock to send 'data' (when not busy)\n    input  wire [7:0] data,\n    output reg        tx,        // serial line, idles high\n    output wire       busy\n);\n    localparam [1:0] IDLE = 2'd0, START = 2'd1, DATA = 2'd2, STOP = 2'd3;\n    localparam W = $clog2(CLKS_PER_BIT);\n\n    reg [1:0]   state;\n    reg [W-1:0] count;\n    reg [2:0]   index;\n    reg [7:0]   shift;\n\n    wire bit_done = (count == CLKS_PER_BIT - 1);\n    assign busy = (state != IDLE);\n\n    always @(posedge clk) begin\n        if (rst) begin\n            state <= IDLE; tx <= 1'b1; count <= {W{1'b0}}; index <= 3'd0; shift <= 8'd0;\n        end else begin\n            if (state == IDLE || bit_done) count <= {W{1'b0}};\n            else                           count <= count + 1'b1;\n\n            case (state)\n                IDLE: begin\n                    tx <= 1'b1;\n                    if (start) begin shift <= data; state <= START; end\n                end\n                START: begin\n                    tx <= 1'b0;\n                    if (bit_done) begin index <= 3'd0; state <= DATA; end\n                end\n                DATA: begin\n                    tx <= shift[index];\n                    if (bit_done) begin\n                        if (index == 3'd7) state <= STOP;\n                        else               index <= index + 1'b1;\n                    end\n                end\n                STOP: begin\n                    tx <= 1'b1;\n                    if (bit_done) state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule\n","sv":"// UART transmitter, 8N1: start bit (0), 8 data bits (lowest first), stop bit (1).\n// CLKS_PER_BIT = clock frequency / baud rate.  Example: 12 MHz / 115200 = 104.\nmodule uart_tx #(parameter int CLKS_PER_BIT = 104) (\n    input  logic       clk,\n    input  logic       rst,\n    input  logic       start,    // pulse for one clock to send 'data' (when not busy)\n    input  logic [7:0] data,\n    output logic       tx,       // serial line, idles high\n    output logic       busy\n);\n    typedef enum logic [1:0] { IDLE, START, DATA, STOP } state_t;\n    localparam int W = $clog2(CLKS_PER_BIT);\n\n    state_t       state;\n    logic [W-1:0] count;\n    logic [2:0]   index;\n    logic [7:0]   shift;\n\n    wire bit_done = (count == CLKS_PER_BIT - 1);\n    assign busy = (state != IDLE);\n\n    always_ff @(posedge clk) begin\n        if (rst) begin\n            state <= IDLE; tx <= 1'b1; count <= '0; index <= '0; shift <= '0;\n        end else begin\n            if (state == IDLE || bit_done) count <= '0;\n            else                           count <= count + 1'b1;\n\n            case (state)\n                IDLE: begin\n                    tx <= 1'b1;\n                    if (start) begin shift <= data; state <= START; end\n                end\n                START: begin\n                    tx <= 1'b0;\n                    if (bit_done) begin index <= '0; state <= DATA; end\n                end\n                DATA: begin\n                    tx <= shift[index];\n                    if (bit_done) begin\n                        if (index == 3'd7) state <= STOP;\n                        else               index <= index + 1'b1;\n                    end\n                end\n                STOP: begin\n                    tx <= 1'b1;\n                    if (bit_done) state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_uart_tx;\n    reg        clk = 0, rst = 1, start = 0;\n    reg  [7:0] data = 0;\n    wire       tx, busy;\n    reg  [7:0] sent [0:63];\n    reg  [7:0] rx_byte;\n    integer i, k, received = 0, errors = 0;\n\n    uart_tx #(.CLKS_PER_BIT(8)) dut (.clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy));\n    always #5 clk = ~clk;                       // one bit = 8 clocks = 80 ns\n\n    // an independent receiver that decodes the serial line by timing alone\n    initial begin\n        wait (rst == 0);\n        forever begin\n            @(negedge tx);\n            #40 if (tx !== 1'b0) begin errors = errors + 1; $display(\"FAIL: bad start bit\"); end\n            for (k = 0; k < 8; k = k + 1) begin #80; rx_byte[k] = tx; end\n            #80 if (tx !== 1'b1) begin errors = errors + 1; $display(\"FAIL: bad stop bit\"); end\n            if (rx_byte !== sent[received]) begin errors = errors + 1; $display(\"FAIL: got %h expected %h\", rx_byte, sent[received]); end\n            received = received + 1;\n        end\n    end\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_uart_tx);\n        repeat (4) @(negedge clk);\n        rst = 0;\n        repeat (4) @(negedge clk);\n        for (i = 0; i < 50; i = i + 1) begin\n            data = (i == 0) ? 8'h00 : (i == 1) ? 8'hFF : (i == 2) ? 8'h55 : $random;\n            sent[i] = data;\n            start = 1; @(negedge clk); start = 0;\n            if (!busy) begin errors = errors + 1; $display(\"FAIL: busy not set\"); end\n            data = 8'hxx;                       // changing data now must not matter\n            wait (busy == 0);\n            repeat ($random & 7) @(negedge clk);\n            @(negedge clk);\n        end\n        #2000;\n        if (errors == 0 && received == 50) $display(\"PASS: uart_tx, 50 bytes decoded correctly from the serial line\");\n        else                               $display(\"FAIL: %0d errors, %0d bytes received\", errors, received);\n        $finish;\n    end\nendmodule\n"},{"id":"uart_rx","title":"UART receiver","group":"Interfaces","level":"Advanced","summary":"Receives serial bytes, sampling in the middle of each bit and reporting bad frames.","how":["Two flip-flops synchronize the incoming line.","After the start edge it waits half a bit, then samples once per bit time.","Short glitches are ignored, and a bad stop bit raises frame_error."],"try":"Connect it to uart_tx (tx to rx) and write a testbench that echoes bytes.","expect":"PASS: uart_rx, 51 bytes received, glitch ignored, 1 frame error caught","v":"// UART receiver, 8N1. It looks for the falling edge of the start bit, then samples each bit\n// in the MIDDLE. CLKS_PER_BIT = clock frequency / baud rate (12 MHz / 115200 = 104).\nmodule uart_rx #(parameter CLKS_PER_BIT = 104) (\n    input  wire       clk,\n    input  wire       rst,\n    input  wire       rx,           // serial input (may be from another clock)\n    output reg  [7:0] data,\n    output reg        valid,        // high for one clock when 'data' is new\n    output reg        frame_error   // high for one clock when the stop bit was wrong\n);\n    localparam [2:0] IDLE = 3'd0, START = 3'd1, DATA = 3'd2, STOP = 3'd3, RECOVER = 3'd4;\n    localparam W = $clog2(CLKS_PER_BIT);\n\n    reg         rx_meta, rx_sync;   // 2-flip-flop synchronizer\n    reg [2:0]   state;\n    reg [W-1:0] count;\n    reg [2:0]   index;\n    reg [7:0]   shift;\n\n    always @(posedge clk) begin\n        if (rst) begin rx_meta <= 1'b1; rx_sync <= 1'b1; end\n        else     begin rx_meta <= rx;   rx_sync <= rx_meta; end\n    end\n\n    always @(posedge clk) begin\n        if (rst) begin\n            state <= IDLE; count <= {W{1'b0}}; index <= 3'd0; shift <= 8'd0;\n            data <= 8'd0; valid <= 1'b0; frame_error <= 1'b0;\n        end else begin\n            valid <= 1'b0; frame_error <= 1'b0;\n            count <= count + 1'b1;\n            case (state)\n                IDLE: begin\n                    count <= {W{1'b0}};\n                    if (!rx_sync) state <= START;\n                end\n                START: if (count == CLKS_PER_BIT/2 - 1) begin      // middle of the start bit\n                    count <= {W{1'b0}}; index <= 3'd0;\n                    state <= rx_sync ? IDLE : DATA;                // too short = just noise\n                end\n                DATA: if (count == CLKS_PER_BIT - 1) begin\n                    count <= {W{1'b0}};\n                    shift[index] <= rx_sync;\n                    if (index == 3'd7) state <= STOP;\n                    else               index <= index + 1'b1;\n                end\n                STOP: if (count == CLKS_PER_BIT - 1) begin\n                    count <= {W{1'b0}};\n                    if (rx_sync) begin data <= shift; valid <= 1'b1; state <= IDLE; end\n                    else         begin frame_error <= 1'b1;          state <= RECOVER; end\n                end\n                RECOVER: if (rx_sync) state <= IDLE;               // wait for the line to go high\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule\n","sv":"// UART receiver, 8N1. It looks for the falling edge of the start bit, then samples each bit\n// in the MIDDLE. CLKS_PER_BIT = clock frequency / baud rate (12 MHz / 115200 = 104).\nmodule uart_rx #(parameter int CLKS_PER_BIT = 104) (\n    input  logic       clk,\n    input  logic       rst,\n    input  logic       rx,           // serial input (may be from another clock)\n    output logic [7:0] data,\n    output logic       valid,        // high for one clock when 'data' is new\n    output logic       frame_error   // high for one clock when the stop bit was wrong\n);\n    typedef enum logic [2:0] { IDLE, START, DATA, STOP, RECOVER } state_t;\n    localparam int W = $clog2(CLKS_PER_BIT);\n\n    logic         rx_meta, rx_sync; // 2-flip-flop synchronizer\n    state_t       state;\n    logic [W-1:0] count;\n    logic [2:0]   index;\n    logic [7:0]   shift;\n\n    always_ff @(posedge clk) begin\n        if (rst) begin rx_meta <= 1'b1; rx_sync <= 1'b1; end\n        else     begin rx_meta <= rx;   rx_sync <= rx_meta; end\n    end\n\n    always_ff @(posedge clk) begin\n        if (rst) begin\n            state <= IDLE; count <= '0; index <= 3'd0; shift <= 8'd0;\n            data <= 8'd0; valid <= 1'b0; frame_error <= 1'b0;\n        end else begin\n            valid <= 1'b0; frame_error <= 1'b0;\n            count <= count + 1'b1;\n            case (state)\n                IDLE: begin\n                    count <= '0;\n                    if (!rx_sync) state <= START;\n                end\n                START: if (count == CLKS_PER_BIT/2 - 1) begin      // middle of the start bit\n                    count <= '0; index <= 3'd0;\n                    if (rx_sync) state <= IDLE;                    // too short = just noise\n                    else         state <= DATA;\n                end\n                DATA: if (count == CLKS_PER_BIT - 1) begin\n                    count <= '0;\n                    shift[index] <= rx_sync;\n                    if (index == 3'd7) state <= STOP;\n                    else               index <= index + 1'b1;\n                end\n                STOP: if (count == CLKS_PER_BIT - 1) begin\n                    count <= '0;\n                    if (rx_sync) begin data <= shift; valid <= 1'b1; state <= IDLE; end\n                    else         begin frame_error <= 1'b1;          state <= RECOVER; end\n                end\n                RECOVER: if (rx_sync) state <= IDLE;               // wait for the line to go high\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_uart_rx;\n    reg        clk = 0, rst = 1, rx = 1;\n    wire [7:0] data;\n    wire       valid, frame_error;\n    reg  [7:0] sent [0:63];\n    reg  [7:0] b;\n    integer i, k, received = 0, ferrs = 0, errors = 0;\n\n    uart_rx #(.CLKS_PER_BIT(8)) dut (.clk(clk), .rst(rst), .rx(rx), .data(data), .valid(valid), .frame_error(frame_error));\n    always #5 clk = ~clk;                       // one bit = 80 ns\n\n    always @(negedge clk) begin\n        if (valid) begin\n            if (data !== sent[received]) begin errors = errors + 1; $display(\"FAIL: got %h expected %h\", data, sent[received]); end\n            received = received + 1;\n        end\n        if (frame_error) ferrs = ferrs + 1;\n    end\n\n    task send(input [7:0] value, input good_stop);\n        begin\n            rx = 0; #80;\n            for (k = 0; k < 8; k = k + 1) begin rx = value[k]; #80; end\n            rx = good_stop; #80;\n            rx = 1;\n        end\n    endtask\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_uart_rx);\n        #52 rst = 0;\n        #203;                                   // start at a time unrelated to the clock edges\n        for (i = 0; i < 50; i = i + 1) begin\n            b = (i == 0) ? 8'h00 : (i == 1) ? 8'hFF : (i == 2) ? 8'hA5 : $random;\n            sent[i] = b;\n            send(b, 1);\n            #($urandom % 200);\n        end\n        #300 rx = 0; #20 rx = 1;                // a short glitch: must be ignored\n        #1500;\n        send(8'h3C, 0);                         // broken stop bit: must report a frame error\n        #1000;\n        sent[50] = 8'h7E; send(8'h7E, 1);       // and it must recover afterwards\n        #1000;\n        if (errors == 0 && received == 51 && ferrs == 1) $display(\"PASS: uart_rx, 51 bytes received, glitch ignored, 1 frame error caught\");\n        else $display(\"FAIL: %0d errors, %0d bytes, %0d frame errors\", errors, received, ferrs);\n        $finish;\n    end\nendmodule\n"},{"id":"spi_master","title":"SPI master","group":"Interfaces","level":"Advanced","summary":"Talks to sensors, flash memory and displays over SPI (mode 0).","how":["cs_n goes low to select the device.","Data is read on the rising edge of sclk and changed on the falling edge, most significant bit first.","Sending and receiving happen at the same time."],"try":"Make the transfer width a parameter (8, 16 or 32 bits).","expect":"PASS: spi_master, 200 two-way transfers","v":"// SPI master, mode 0 (CPOL = 0, CPHA = 0), 8 bits, most significant bit first.\n// Both sides read data on the RISING edge of sclk and change it on the FALLING edge.\n// One half period of sclk lasts CLK_DIV system clocks.\nmodule spi_master #(parameter CLK_DIV = 4) (\n    input  wire       clk,\n    input  wire       rst,\n    input  wire       start,      // pulse to send tx_data (when not busy)\n    input  wire [7:0] tx_data,\n    input  wire       miso,       // master in, slave out\n    output reg        sclk,\n    output wire       mosi,       // master out, slave in\n    output reg        cs_n,       // chip select, active low\n    output reg  [7:0] rx_data,\n    output wire       busy,\n    output reg        done        // high for one clock when rx_data is ready\n);\n    localparam [1:0] IDLE = 2'd0, LOW = 2'd1, HIGH = 2'd2, FINISH = 2'd3;\n    localparam W = $clog2(CLK_DIV + 1);\n\n    reg [1:0]   state;\n    reg [W-1:0] count;\n    reg [2:0]   index;\n    reg [7:0]   tx_shift, rx_shift;\n\n    wire half_done = (count == CLK_DIV - 1);\n    assign busy = (state != IDLE);\n    assign mosi = tx_shift[7];\n\n    always @(posedge clk) begin\n        if (rst) begin\n            state <= IDLE; sclk <= 1'b0; cs_n <= 1'b1; done <= 1'b0;\n            count <= {W{1'b0}}; index <= 3'd0; tx_shift <= 8'd0; rx_shift <= 8'd0; rx_data <= 8'd0;\n        end else begin\n            done <= 1'b0;\n            if (state == IDLE || half_done) count <= {W{1'b0}};\n            else                            count <= count + 1'b1;\n\n            case (state)\n                IDLE: if (start) begin\n                    cs_n <= 1'b0; tx_shift <= tx_data; index <= 3'd0; state <= LOW;\n                end\n                LOW: if (half_done) begin\n                    sclk <= 1'b1;                           // rising edge: read miso\n                    rx_shift <= {rx_shift[6:0], miso};\n                    state <= HIGH;\n                end\n                HIGH: if (half_done) begin\n                    sclk <= 1'b0;                           // falling edge: next bit out\n                    if (index == 3'd7) state <= FINISH;\n                    else begin\n                        index <= index + 1'b1;\n                        tx_shift <= {tx_shift[6:0], 1'b0};\n                        state <= LOW;\n                    end\n                end\n                FINISH: if (half_done) begin\n                    cs_n <= 1'b1; rx_data <= rx_shift; done <= 1'b1; state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule\n","sv":"// SPI master, mode 0 (CPOL = 0, CPHA = 0), 8 bits, most significant bit first.\n// Both sides read data on the RISING edge of sclk and change it on the FALLING edge.\n// One half period of sclk lasts CLK_DIV system clocks.\nmodule spi_master #(parameter int CLK_DIV = 4) (\n    input  logic       clk,\n    input  logic       rst,\n    input  logic       start,      // pulse to send tx_data (when not busy)\n    input  logic [7:0] tx_data,\n    input  logic       miso,       // master in, slave out\n    output logic       sclk,\n    output logic       mosi,       // master out, slave in\n    output logic       cs_n,       // chip select, active low\n    output logic [7:0] rx_data,\n    output logic       busy,\n    output logic       done        // high for one clock when rx_data is ready\n);\n    typedef enum logic [1:0] { IDLE, LOW, HIGH, FINISH } state_t;\n    localparam int W = $clog2(CLK_DIV + 1);\n\n    state_t       state;\n    logic [W-1:0] count;\n    logic [2:0]   index;\n    logic [7:0]   tx_shift, rx_shift;\n\n    wire half_done = (count == CLK_DIV - 1);\n    assign busy = (state != IDLE);\n    assign mosi = tx_shift[7];\n\n    always_ff @(posedge clk) begin\n        if (rst) begin\n            state <= IDLE; sclk <= 1'b0; cs_n <= 1'b1; done <= 1'b0;\n            count <= '0; index <= 3'd0; tx_shift <= 8'd0; rx_shift <= 8'd0; rx_data <= 8'd0;\n        end else begin\n            done <= 1'b0;\n            if (state == IDLE || half_done) count <= '0;\n            else                            count <= count + 1'b1;\n\n            case (state)\n                IDLE: if (start) begin\n                    cs_n <= 1'b0; tx_shift <= tx_data; index <= 3'd0; state <= LOW;\n                end\n                LOW: if (half_done) begin\n                    sclk <= 1'b1;                           // rising edge: read miso\n                    rx_shift <= {rx_shift[6:0], miso};\n                    state <= HIGH;\n                end\n                HIGH: if (half_done) begin\n                    sclk <= 1'b0;                           // falling edge: next bit out\n                    if (index == 3'd7) state <= FINISH;\n                    else begin\n                        index <= index + 1'b1;\n                        tx_shift <= {tx_shift[6:0], 1'b0};\n                        state <= LOW;\n                    end\n                end\n                FINISH: if (half_done) begin\n                    cs_n <= 1'b1; rx_data <= rx_shift; done <= 1'b1; state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule\n","tb":"`timescale 1ns/1ps\nmodule tb_spi_master;\n    reg        clk = 0, rst = 1, start = 0;\n    reg  [7:0] tx_data = 0;\n    wire [7:0] rx_data;\n    wire       sclk, mosi, cs_n, busy, done, miso;\n    reg  [7:0] slave_tx = 0, slave_shift = 0, slave_rx = 0;\n    integer i, edges = 0, errors = 0;\n\n    spi_master #(.CLK_DIV(3)) dut (.clk(clk), .rst(rst), .start(start), .tx_data(tx_data), .miso(miso), .sclk(sclk),\n                                   .mosi(mosi), .cs_n(cs_n), .rx_data(rx_data), .busy(busy), .done(done));\n    always #5 clk = ~clk;\n\n    // a simple SPI slave (mode 0)\n    always @(negedge cs_n) slave_shift = slave_tx;\n    assign miso = slave_shift[7];\n    always @(posedge sclk) if (!cs_n) begin slave_rx <= {slave_rx[6:0], mosi}; edges = edges + 1; end\n    always @(negedge sclk) if (!cs_n) slave_shift <= {slave_shift[6:0], 1'b0};\n\n    initial begin\n        $dumpfile(\"wave.vcd\"); $dumpvars(0, tb_spi_master);\n        repeat (3) @(negedge clk);\n        rst = 0;\n        for (i = 0; i < 200; i = i + 1) begin\n            tx_data = $random; slave_tx = $random; edges = 0;\n            @(negedge clk); start = 1; @(negedge clk); start = 0;\n            @(posedge done); @(negedge clk);\n            if (rx_data !== slave_tx || slave_rx !== tx_data || edges != 8 || cs_n !== 1'b1 || sclk !== 1'b0) begin\n                errors = errors + 1;\n                if (errors < 5) $display(\"FAIL: transfer %0d master got %h (slave sent %h), slave got %h (master sent %h), %0d clocks\", i, rx_data, slave_tx, slave_rx, tx_data, edges);\n            end\n            repeat ($random & 3) @(negedge clk);\n        end\n        if (errors == 0) $display(\"PASS: spi_master, 200 two-way transfers\");\n        else             $display(\"FAIL: %0d errors\", errors);\n        $finish;\n    end\nendmodule\n"}];
